import { beforeAll, expect, it } from "vite-plus/test";
import { writeFileSync } from "node:fs";
import type { StateCheckpoint } from "../engine/dist/declaration/index.mjs";
import { createConcreteRuntime } from "../src/concrete/runtime.js";
import { getSymbolicEngine } from "../src/symbolic/load-engine.js";
import { buildScriptFixture } from "./helpers/build-script-fixture.js";
import { createNativeRuntime } from "./helpers/native-runtime.js";

let source: string;
beforeAll(async () => {
  source = (await buildScriptFixture(new URL("./fixtures/symbolic-react-tree.tsx", import.meta.url), "production")).code;
});

const diagnosePartialFork = async (isReversed: boolean) => {
  const runtime = await createConcreteRuntime();
  const { api } = await getSymbolicEngine();
  const observations: unknown[] = [];
  let prefixCount = 0;
  let timerCount: number | undefined;
  let referenceRecordCount: number | undefined;
  let nativeListCount: number | undefined;
  const rejectedLists: { keys: string[]; error: string }[] = [];
  let frontier: unknown;
  let failureStack = "";
  const recordShapes = new Map<string, number>();
  try {
    runtime.evaluate(source);
    runtime.evaluate("fixture.mount()");
    runtime.drainJobs();
    const previous = api.surroundingAgent;
    api.setSurroundingAgent(runtime.agent);
    try {
      const enabledInput = api.BooleanValue.createAbstract();
      const detailsInput = api.BooleanValue.createAbstract();
      api.X(api.CreateDataPropertyOrThrow(runtime.realm.GlobalObject, "enabled", enabledInput));
      api.X(api.CreateDataPropertyOrThrow(runtime.realm.GlobalObject, "details", detailsInput));
      const onNodeEvaluation = runtime.agent.hostDefinedOptions.onNodeEvaluation;
      runtime.agent.hostDefinedOptions.onNodeEvaluation = (node, realm) => {
        onNodeEvaluation?.(node, realm);
        if (node.type === "UnaryExpression" && node.sourceText === "void 1") prefixCount++;
      };
      runtime.evaluate("var reachedTimer = false");
      const compiled = api.EnsureCompletion(runtime.realm.compileScript(`
        void 1;
        fixture.update(enabled, details);
        Date.now();
        reachedTimer = true;
        setTimeout(() => console.log("partial-owner-branch"), 0);
        fixture.observe();
      `));
      if (compiled.Type !== "normal") throw Error("Expected script");
      runtime.agent.evaluate(api.ScriptEvaluation(compiled.Value), () => {}, false);
      const pause = runtime.agent.resumeEvaluate({ pauseOnAbstractBoolean: true, noBreakpoint: true });
      if (pause.done || !pause.value) throw Error("Expected decision");
      const seen = new Set<object>();
      const contexts = [...runtime.agent.executionContextStack];
      let storage: StateCheckpoint | undefined;
      let releaseHost = () => {};
      const checkpoint = runtime.agent.captureEvaluation({
        references: value => {
          if (seen.size >= 50000) throw Error("Diagnostic reference budget exceeded");
          seen.add(value);
          const references: unknown[] = [];
          if (value instanceof api.ObjectValue) {
            const entries = api.isMapObject(value) ? value.MapData : api.isWeakMapObject(value) ? value.WeakMapData : undefined;
            for (const entry of entries ?? []) references.push(entry.Key, entry.Value);
          }
          if (value instanceof api.CallSite) references.push(value.context);
          if (Array.isArray(value)) references.push(...value);
          else if (typeof Reflect.get(value, "mark") === "function") Reflect.apply(Reflect.get(value, "mark"), value, [(reference: unknown) => references.push(reference)]);
          return references;
        },
        capture: roots => {
          for (const value of seen) {
            if (typeof value === "function" || Array.isArray(value) || value instanceof api.Value || value instanceof api.EnvironmentRecord || value instanceof api.ExecutionContext || value instanceof api.CallSite || value instanceof api.ReferenceRecord) continue;
            const prototype = Object.getPrototypeOf(value);
            const constructor = prototype && Object.getOwnPropertyDescriptor(prototype, "constructor")?.value;
            const name = typeof constructor === "function" ? Object.getOwnPropertyDescriptor(constructor, "name")?.value : "null";
            const shape = `${name}: ${Reflect.ownKeys(value).map(String).sort().join(",")}`;
            recordShapes.set(shape, (recordShapes.get(shape) ?? 0) + 1);
          }
          const functions = [...seen].filter(value => typeof value === "function");
          const registered = functions.filter(value => api.getNativeCaptures(value) !== undefined);
          const unregistered = functions.filter(value => api.getNativeCaptures(value) === undefined);
          const names = [...new Set(unregistered.map(value => value.name))].sort();
          frontier = {
            distinctReferences: seen.size,
            guestObjects: [...seen].filter(value => value instanceof api.ObjectValue).length,
            nativeArrays: [...seen].filter(value => Array.isArray(value)).length,
            nativeFunctions: functions.length,
            registered: registered.length,
            functionsWithStepsBinding: registered.filter(value => api.getNativeCaptures(value)?.bindings.some(binding => binding.name === "steps")).length,
            unregistered: Object.fromEntries(names.map(name => [name, unregistered.filter(value => value.name === name).length])),
          };
          const nativeLists: unknown[][] = [];
          for (const value of seen) {
            if (!Array.isArray(value) || roots.controlOwnedObjects.includes(value)) continue;
            try {
              const selected = api.createStateCheckpoint({ nativeLists: [value] });
              selected.release();
              nativeLists.push(value);
            } catch (error) {
              rejectedLists.push({ keys: Reflect.ownKeys(value).map(String), error: String(error) });
            }
          }
          const state = api.createStateCheckpoint({
            nativeLists,
            objects: [...seen].filter(value => value instanceof api.ObjectValue),
            environments: [...seen].filter(value => value instanceof api.DeclarativeEnvironmentRecord || value instanceof api.GlobalEnvironmentRecord),
            contexts: [...seen].filter(value => value instanceof api.ExecutionContext),
            callSites: [...seen].filter(value => value instanceof api.CallSite),
            referenceRecords: [...seen].filter(value => value instanceof api.ReferenceRecord),
          });
          storage = state;
          referenceRecordCount = state.referenceRecordCount;
          nativeListCount = state.nativeListCount;
          expect(nativeListCount).toBeGreaterThan(0);
          expect(referenceRecordCount).toBeGreaterThan(0);
          const host = runtime.captureHostState();
          timerCount = host.timerCount;
          releaseHost = host.release;
          return { restore: () => {
            host.restore();
            state.restore();
            runtime.agent.executionContextStack.splice(0, runtime.agent.executionContextStack.length, ...contexts);
          } };
        },
      });
      try {
        const assignments = [false, true].flatMap(enabled => [false, true].map(details => ({ enabled, details })));
        for (const assignment of isReversed ? assignments.reverse() : assignments) {
          checkpoint.restore();
          runtime.agent.AgentRecord.KeptAlive.clear();
          api.gc();
          let decision = pause.value;
          let result;
          let decisions = 0;
          while (true) {
            if (++decisions > 16) throw Error("Decision budget exceeded");
            const choice = decision.value === enabledInput ? assignment.enabled : decision.value === detailsInput ? assignment.details : undefined;
            if (choice === undefined) throw Error("Lost input identity");
            result = runtime.agent.resumeEvaluate({ abstractBooleanDecision: { resume: "abstract-boolean", decision, value: choice }, noBreakpoint: true });
            if (result.done) break;
            if (!result.value) throw Error("Unexpected pause");
            decision = result.value;
            runtime.agent.AgentRecord.KeptAlive.clear();
            api.gc();
          }
          const completion = api.EnsureCompletion(result.value);
          if (completion.Type !== "normal" || !(completion.Value instanceof api.JSStringValue)) throw Error("Expected tree observation");
          const actual = completion.Value.stringValue();
          const native = createNativeRuntime();
          native.evaluate(source);
          native.evaluate("fixture.mount()");
          native.drainJobs();
          native.evaluate(`fixture.update(${assignment.enabled}, ${assignment.details})`);
          const expected = native.evaluate("fixture.observe()");
          observations.push({ ...assignment, actual, expected, decisions });
          expect(actual).toBe(expected);
        }
      } finally {
        checkpoint.release();
        storage?.release();
        releaseHost();
      }
    } finally { api.setSurroundingAgent(previous); }
    expect(prefixCount).toBe(1);
    runtime.drainJobs();
    const leakedTimers = runtime.consoleEntries.filter(entry => entry.arguments[0] instanceof api.JSStringValue && entry.arguments[0].stringValue() === "partial-owner-branch").length;
    observations.push({ leakedTimers, expectedForOneBranch: 1 });
    expect(leakedTimers).toBe(4);
  } catch (error) {
    if (error instanceof Error) failureStack = error.stack ?? "";
    throw error;
  } finally {
    const reachedTimer = runtime.realm.GlobalObject.properties.get("reachedTimer")?.Value === api.Value.true;
    expect(prefixCount).toBe(1);
    const phase = failureStack.includes("HostSystemUTCEpochNanoseconds") ? "clock" : reachedTimer ? "timer" : "unknown";
    expect(phase).toBe(process.env.BIPPY_REJECTION_PHASE ?? "clock");
    expect(observations).toEqual([]);
    writeFileSync(`/tmp/bippy-react-nondeterminism-${phase}-${isReversed}.json`, JSON.stringify({ phase, failureStack, recordShapes: Object.fromEntries(recordShapes), prefixCount, reachedTimer, timerCount, referenceRecordCount, nativeListCount, rejectedLists, frontier, observations, limitation: "Selected canonical native lists now restore their own indexed entries and length. Other layouts, element contents, native records and callbacks remain unowned. The diagnostic records the first rejection phase. The maintained guard rejects an explicit application Date.now call after React update, before the previous timer boundary; selection counts are not execution ownership." }, null, 2));
    runtime.dispose();
  }
};

it.each([false, true])("rejects partial-owner React timer scheduling, reversed=%s", async isReversed => {
  await expect(diagnosePartialFork(isReversed)).rejects.toThrow("Host effects are unsupported during evaluation checkpoints");
});

